    ["<Highlight>星之虫</>类型的秘偶，可以<Highlight>幻化</>成其他非凡者。幻化后可以<Highlight>自由装扮</>。"] = "Марионетки типа <Highlight>Звёздный червь</> могут <Highlight>преображаться</> в других Потусторонних. После преображения можно <Highlight>свободно наряжать</> их.",
    ["<Highlight>消化进度的上限</>会随<Highlight>赛季天数</>解锁。"] = "<Highlight>Предел прогресса усвоения</> повышается с <Highlight>днями сезона</>.",
    ["<Highlight>蓝圈</>出现时，使用<Orange>猎魔子弹</>反击攻击！"] = "Когда появится <Highlight>Синий круг</>, используйте <Orange>Пуля охотника на демонов</> для контратаки!",
