    ["当所有条件满足时，点击此处升级城堡。"] = "Когда все условия будут выполнены, нажмите здесь для улучшения замка.",
    ["当满足<Highlight>城堡升级条件</>、<Highlight>消耗</>一定数量的城堡资产即可升级城堡。"] = "Когда вы соответствуете условиям обновления замка <Highlight></> и <Highlight>, потребляете </> определенное количество активов замка, вы можете улучшить замок.",
    ["您也可以自行装修城堡，点击此处打开<Highlight>装修</>界面"] = "Вы также можете украсить замок самостоятельно. Нажмите здесь, чтобы открыть интерфейс <Highlight>Decoration</>.",
    ["打开<Highlight>城市暗面</>。"] = "Откройте <Highlight>тёмную сторону города</>.",
    ["打开木桩设置界面。"] = "Откройте интерфейс фиктивных настроек.",
    ["打开菜单。"] = "Открыть меню.",
    ["找到<Orange>检视线索</>进行检视，点击<Orange>放大镜</>进行检视。"] = "Найдите <Orange>Подсказки расследования</> для проверки и щелкните <Orange>Увеличительное стекло</>, чтобы проверить.",
    ["找到可附身的动物后，可使用附身技能操控。"] = "Найдя подходящее животное, примените навык одержимости, чтобы взять его под контроль.",
    ["拖动轮盘进行移动"] = "Перетащите колесо, чтобы двигаться",
    ["指派完成后点击<Highlight>开始建造</>进行建造。"] = "После назначения нажмите <Highlight>Начать строительство</>, чтобы начать строительство.",
    ["指派更多的秘偶可以<Highlight>缩短建造时长</>。"] = "Назначение большего количества марионеток может <Highlight> сократить время строительства</>.",
    ["按 <img id=\"KeyPrompt_W\" width=\"33\" height=\"38\"/> 向前移动"] = "Нажмите <img id=\"KeyPrompt_W\" width=\"33\" height=\"38\"/>, чтобы двигаться вперед.",
    ["按下 <img id=\"KeyPrompt_W\" width=\"33\" height=\"38\"/><img id=\"KeyPrompt_A\" width=\"33\" height=\"38\"/><img id=\"KeyPrompt_S\" width=\"33\" height=\"38\"/><img id=\"KeyPrompt_D\" width=\"33\" height=\"38\"/> 移动"] = "Нажмите <img id=\"KeyPrompt_W\" width=\"33\" height=\"38\"/><img id=\"KeyPrompt_A\" width=\"33\" height=\"38\"/><img id=\"KeyPrompt_S\" width=\"33\" height=\"38\"/><img id=\"KeyPrompt_D\" width=\"33\" height=\"38\"/> для перемещения.",
    ["按住 <img id=\"KeyPrompt_LeftMouseButton\" width=\"33\" height=\"41\"/> 圈出想要生成建筑的<Highlight>区域</>。"] = "Удерживайте <img id=\"KeyPrompt_LeftMouseButton\" width=\"33\" height=\"41\"/>, чтобы обвести область <Highlight></>, где вы хотите построить здание.",
    ["探秘属性可通过探秘天赋进行提升。"] = "Атрибуты исследования можно улучшить с помощью талантов исследования.",
    ["接下来我们就可以购买货物，开始致富之旅"] = "Далее мы можем купить товары и начать путь к богатству.",
    ["搭配完成后，别忘记确认，保存你的最终选择"] = "После завершения наряда не забудьте подтвердить и сохранить окончательный выбор.",
    ["携带推荐的物品价值更高，根据每周推荐调整携带物品会更有效率"] = "Ношение рекомендованных предметов имеет более высокую ценность; корректировка переносимых товаров на основе еженедельных рекомендаций будет более эффективной.",
    ["攻略助手已经解锁，点击此处查看。"] = "Руководство разблокировано, нажмите здесь для просмотра.",
    ["新获得的恩赐词条，可以设置触发保存它的条件，也可以放弃将其保存在神之空间内。"] = "Для недавно полученных аффиксов Дара вы можете установить условия для их срабатывания и сохранения или можете отказаться от них вместо сохранения в Божественном Пространстве.",
    ["更多封印物系统信息，可以点击说明书查看。"] = "Для получения дополнительной информации о системе «Запечатанный артефакт» щелкните руководство, чтобы просмотреть его.",
    ["更多改装规则，可查看说明。"] = "Дополнительные правила модификации можно посмотреть в инструкции.",
    ["有各个方向的<Highlight>序列任务</>可供选择。"] = "Для выбора доступны <Highlight>Sequence Quests</> по различным направлениям.",
    ["查看可置换词条。"] = "Просмотр сменных аффиксов.",
    ["根据按键提示完成连招"] = "Выполните комбо по подсказкам кнопок",
    ["根据搭配，这里会实时更新你的搭配总评分"] = "В зависимости от подбора наряда здесь в реальном времени обновляется общий рейтинг стиля",
    ["格罗塞尔游记的投影赋予你进入书页的能力，点击菜单查看。"] = "Проекция «Путешествий Грозель» дает вам возможность попасть на страницы книги. Нажмите на меню, чтобы просмотреть его.",
    ["模板功能已解锁，点击查看。"] = "Функция шаблона разблокирована; нажмите, чтобы просмотреть.",
    ["欢迎参与歌剧魅影比赛，搭配好<Highlight>外观</>即可参与华丽对决！"] = "Добро пожаловать на состязание «Призрак оперы». Подберите <Highlight>внешний вид</> и участвуйте в великолепной дуэли!",
    ["欢迎来到铁路大亨，交易之旅即将开始"] = "Добро пожаловать в «Железнодорожный магнат»; торговое путешествие вот-вот начнется.",
    ["歌剧魅影比赛中可以选择拥有的各种外观进行搭配"] = "В конкурсе «Призрак Оперы» вы можете выбирать для координации различные образы, которые у вас есть.",
    ["此处会显示<Highlight>附近站点</>的物资收购情况。"] = "Здесь отображается состояние закупки припасов на <Highlight>ближайших станциях</>.",
    ["此处会显示当前站点的<Highlight>税率</>和您的<Highlight>负重</>。购买物资后，负重不可超过上限。后续升级马车，可以降低税率并提高负重上限。"] = "Здесь отображаются <Highlight>налоговая ставка</> текущей станции и ваша <Highlight>грузоподъёмность</>. После покупки припасов нагрузка не должна превышать лимит. Улучшив карету, вы сможете снизить налоговую ставку и повысить лимит нагрузки.",
    ["此处会显示近期的物资价格变动记录。每隔一段时间，物资价格就会<Highlight>变动</>一次。"] = "Здесь отображается история недавних изменений цен на припасы. Через некоторое время цены на припасы <Highlight>меняются</>.",
    ["此处可<Highlight>查看、参观</>模板，保存后可以进行<Highlight>应用</>。"] = "Здесь вы можете <Highlight> просматривать и посещать шаблоны </>, а после сохранения вы можете <Highlight> применять </>.",
    ["此处可以使用<Highlight>建造模式</>的相关功能。"] = "Здесь можно использовать функции <Highlight>режима строительства</>.",
    ["此处可以快速查看当前的穿着。"] = "Здесь вы можете быстро просмотреть свой текущий наряд.",
    ["此处可以查看可出售的货物列表。"] = "Здесь можно просмотреть список доступных для продажи товаров.",
    ["此处可以查看当前版本热门推荐内容。"] = "Здесь можно просмотреть популярный рекомендованный контент текущей версии.",
    ["此处可以查看当前站点出售的物资。"] = "Здесь можно посмотреть припасы, которые продаются на текущей станции.",
    ["此处可以看到当前的<Highlight>序列名称</>，以及简单的<Highlight>序列能力</>说明。"] = "Здесь вы можете увидеть текущее имя последовательности <Highlight></> и краткое объяснение способностей последовательности <Highlight></>.",
    ["此处显示当前版本的热门问题。"] = "Здесь отображаются популярные вопросы для текущей версии.",
    ["此处查看可以申请的<Highlight>俱乐部列表</>。"] = "Посмотреть список <Highlight>Club </>, на который вы можете подать заявку, можно здесь.",
    ["此处选择需要的<Highlight>建造风格</>。"] = "Выберите здесь необходимый стиль здания <Highlight></>.",
    ["每个秘偶都能提升<Highlight>角色属性</>，并有独特的<Highlight>技能</>。<Highlight>培养</>秘偶可以强化属性和技能效果。"] = "Каждая марионетка может улучшать <Highlight>Атрибуты персонажа</> и обладает уникальными <Highlight>Skills</>. <Highlight>КультивированиеМарионетки </> могут усиливать атрибуты и эффекты навыков.",
    ["每个站点都有<Highlight>不同</>的委托，完成委托可以获得丰厚的利润奖励。点击<Highlight>此处</>查看委托详情。"] = "На каждой станции свои <Highlight>особые</> поручения; выполнение поручений приносит щедрую прибыль. Нажмите <Highlight>здесь</>, чтобы посмотреть подробности поручения.",
    ["每件封印物的能力不同，它们能带来力量，也会带来一定的负面效果。"] = "Каждый запечатанный артефакт имеет разные способности; они приносят силу, но также и определенные негативные последствия.",
    ["每周需要遵循教团规章，完成指定任务来证明自身行迹。"] = "Каждую неделю вам необходимо следовать правилам культа и выполнять назначенные задания, чтобы доказать свои действия.",
    ["每场比赛会有不同的<Highlight>风格主题</>，对应主题的外观可获得更好成绩"] = "В каждом состязании задаётся особая <Highlight>тематика стиля</>. Образы, соответствующие теме, позволяют набрать больше очков.",
    ["每日完成的<Highlight>前3个</>委托可获得<Highlight>双倍</>收益，每日最多可完成10个委托。"] = "<Highlight>Первые 3</> поручения, выполненные за день, приносят <Highlight>двойную</> награду. В день можно выполнить не более 10 поручений.",
    ["每次改装会增加<Highlight>改装值</>，当<Highlight>改装值</>累积到一定数量时，会解锁新的部位。"] = "Каждая модификация увеличит значение модификации <Highlight></>. Когда значение модификации <Highlight></> накопится до определенной суммы, новые детали будут разблокированы.",
    ["每站结束时，我们都可以使用策略卡来提升收益"] = "В конце каждой станции мы можем использовать стратегические карты для увеличения дохода.",
    ["每贡献1组材料可获得奖励。"] = "Вы можете получать награды за каждый предоставленный набор материалов.",
    ["每贡献一组材料可获得奖励。"] = "Вы можете получать награды за каждый предоставленный набор материалов.",
    ["派遣小星虫去探索吧，可以获得丰厚的奖励。"] = "Отправьте Маленького Звездного Червяка на исследование; вы можете получить щедрое вознаграждение.",
    ["消耗金币使用<Orange>飞掷</>，对普通怪物造成大量伤害"] = "Потребляйте золотые монеты, чтобы использовать <Orange>Throw</>, чтобы нанести огромный урон обычным монстрам.",
    ["消耗金币使用飞掷，对普通怪物造成大量伤害"] = "Потратьте золотые монеты, чтобы использовать «Бросок», наносящий огромный урон обычным монстрам.",
    ["点击<Highlight>一键加点</>。"] = "Нажмите <Highlight> «Обновление в одно касание» </>.",
    ["点击<Highlight>关系</>，打开关系页面。"] = "Нажмите <Highlight>Relationship</>, чтобы открыть страницу отношений.",
    ["点击<Highlight>净化</>按钮可以净化。"] = "Нажмите кнопку <Highlight>Purification</>, чтобы очистить.",
